let isOpen = $state(false);

function toggleDrawer() {
  isOpen = !isOpen;
}

<button id="toggle" on-click={toggleDrawer}>
  Toggle
</button>

<div id="drawer" style={isOpen ? "display: block" : "display: none"}>
  <textarea id="notes"></textarea>
</div>

import { cities } from "../cities.js";

<input
  id="q"
  type="text"
  placeholder="Search cities..."
/>

<ul id="results">
  <for|city| of=cities>
    <li>${city}</li>
  </for>
</ul>

<div id="count">${cities.length} matches</div>

<script>
  const input = document.getElementById("q");
  const resultsList = document.getElementById("results");
  const countDiv = document.getElementById("count");

  // Extract initial city list from DOM
  const allCities = Array.from(resultsList.querySelectorAll("li")).map(li => li.textContent);

  function updateResults() {
    const searchQuery = input.value.toLowerCase();
    const filteredCities = allCities.filter(city =>
      city.toLowerCase().includes(searchQuery)
    );

    // Clear existing results
    resultsList.innerHTML = "";

    // Add filtered cities
    filteredCities.forEach(city => {
      const li = document.createElement("li");
      li.textContent = city;
      resultsList.appendChild(li);
    });

    // Update count
    countDiv.textContent = filteredCities.length + " matches";
  }

  input.addEventListener("input", updateResults);
</script>

export default function middleware(input) {
  const url = new URL(input.request.url, 'http://localhost');
  const key = url.searchParams.get('key');

  if (key !== 'letmein') {
    input.response.statusCode = 401;
    input.response.setHeader('content-type', 'text/plain');
    input.response.end('unauthorized');
  }
}

export async function load({ request }) {
  const url = new URL(request.url);
  const key = url.searchParams.get('key');

  if (key !== 'letmein') {
    throw new Response('unauthorized', { 
      status: 401,
      headers: { 'Content-Type': 'text/plain; charset=utf-8' }
    });
  }
}

